 protected void onCreate(Bundle b){super.onCreate(b);if(getIntent().getBooleanExtra("material",false)){android.content.SharedPreferences a=getSharedPreferences("appearance",0);getSharedPreferences("style-history",0).edit().putInt("theme",a.getInt("theme",0)).putInt("accent",a.getInt("accent",-1)).commit();a.edit().putInt("theme",9).remove("accent").commit();palette=Appearance.palette(this);}home();}
 private void home(){final SharedPreferences p=getSharedPreferences("appearance",0);list("Stil Leo",Arrays.asList("Tema generală · previzualizare","Culoare de accent","Temă pentru fiecare aplicație","Fundal la blocare · "+(p.getBoolean("lock-wallpaper",true)?"Imagine Home":"Culoarea temei"),"Colecții vizuale complete","Telefon · "+(p.getBoolean("unified-phone",false)?"Tema Leo":"Leo Night")),0,new Choice(){public void pick(int i){if(i==4)startActivity(new Intent(StyleSettingsActivity.this,ThemePacksActivity.class));else if(i==5){p.edit().putBoolean("unified-phone",!p.getBoolean("unified-phone",false)).apply();home();}else if(i==0)startActivity(new Intent(StyleSettingsActivity.this,WallpaperActivity.class));else if(i==1){String[] a={"Din temă","Turcoaz","Auriu","Albastru","Roz","Lavandă","Lime"};list("Accent",Arrays.asList(a),Math.max(0,p.getInt("accent",-1)+1),new Choice(){public void pick(int n){sample(null,-1,n-1);}},"",null);back=new Runnable(){public void run(){home();}};}else if(i==2)apps();else{p.edit().putBoolean("lock-wallpaper",!p.getBoolean("lock-wallpaper",true)).apply();home();}}},"",null);}
